function sumRates(...rates) {
  return rates.reduce((sum, r) => sum + r, 0);
}

function exceedsCap(...rates) {
  const total = rates.reduce((sum, r) => sum + r, 0);
  return total > 20;
}

function combineDiscountPercents(...percents) {
  const total = percents.reduce((sum, p) => sum + p, 0);
  return Math.min(total, 20);
}

function combineWithCap(cap, ...percents) {
  const total = percents.reduce((sum, p) => sum + p, 0);
  return Math.min(total, cap);
}

function combineIgnoringNegatives(...percents) {
  const total = percents.reduce((sum, p) => sum + Math.max(p, 0), 0);
  return Math.min(total, 20);
}
